//! CPU mirrors of the MX numeric formats used by the sm_121a kernels.
//!
//! These functions are the *definition* of the M4 dtype contract: they reproduce, bit for bit,
//! the codecs in kernels/m4_common_sm121.cuh. The kernel compiles CUDA's own converters
//! (__nv_cvt_float_to_fp8, __nv_cvt_float_to_fp4) when nvcc is available and the bit-arithmetic
//! fallback otherwise; both must equal these functions, and that is not assumed:
//! tests/m4_codec_golden.rs compares them against a table generated by nvcc 12.9.1 for every one
//! of the 65,536 possible bf16 inputs.
//!
//! Layout contract (identical to the kernels):
//!   * FP8 E4M3: one byte per element, the E4M3 bit pattern;
//!   * FP4 E2M1: two nibbles per byte, low nibble first, no NaN code (0x7 is 6.0);
//!   * ue8m0: one byte per 32-element block, value 2^(bits - 127), 255 reserved as NaN.
//!
//! Numeric contract: round-to-nearest-even, saturating at the format maximum (448 for E4M3,
//! 6 for E2M1). NaN inputs become the E4M3 quiet NaN 0x7F and the E2M1 maximum 0x7, which is
//! what CUDA documents and what the golden table records.

use crate::m4_abi;

/// Values per MX shared scale. Must equal the kernel's SPARK_M4_QUANT_BLOCK.
pub const QUANT_BLOCK: usize = 32;
/// Exponent bias of the ue8m0 scale storage.
pub const UE8M0_BIAS: u8 = 127;
/// Largest legal ue8m0 code; 255 is the reserved all-ones NaN.
pub const UE8M0_MAX: u8 = 254;
/// Maximum exponent of the E4M3 element format, used when deriving a block scale.
pub const E4M3_ELEMENT_EMAX: u32 = 8;
/// Maximum exponent of the E2M1 element format.
pub const E2M1_ELEMENT_EMAX: u32 = 2;

/// Widens a bf16 bit pattern to the f32 value the kernels would load. bf16 to f32 is exact, and
/// a plain shift preserves NaN payloads the same way __bfloat162float does on the device.
#[must_use]
pub fn bf16_bits_to_f32(bits: u16) -> f32 {
    f32::from_bits((bits as u32) << 16)
}

/// Rounds an f32 to bf16 the way the kernels do: the CUDA intrinsic __float2bfloat16_rn, i.e.
/// round to nearest even, which is also what the half crate's bf16::from_f32 implements. Kept here
/// so no reference open-codes a second rounding rule.
#[must_use]
pub fn bf16_bits(value: f32) -> u16 {
    half::bf16::from_f32(value).to_bits()
}

/// The inverse of bf16_bits, so a test can read a reference's output back as a float.
#[must_use]
pub fn bf16_value(bits: u16) -> f32 {
    half::bf16::from_bits(bits).to_f32()
}

/// The E4M3 bit pattern of a value: round-to-nearest-even, saturating to +-448, NaN to 0x7F.
#[must_use]
pub fn fp8_e4m3_encode(value: f32) -> u8 {
    let bits = value.to_bits();
    let sign = (bits >> 31) & 1;
    let exponent = (bits >> 23) & 0xFF;
    let mantissa = bits & 0x007F_FFFF;
    let sign_byte = (sign << 7) as u8;
    let magnitude = bits & 0x7FFF_FFFF;

    if magnitude < 0x0080_0000 {
        // Zero, and float subnormals rounding to the E4M3 subnormal step of 2^-9. Ties at
        // exactly 2^-10 round to the even code, which is zero.
        let rounds_up = f32::from_bits(magnitude) > 0.000_976_562_5;
        return sign_byte | u8::from(rounds_up);
    }
    if exponent == 0xFF {
        if mantissa != 0 {
            return 0x7F; // CUDA returns the canonical positive quiet NaN for either sign
        }
        return sign_byte | 0x7E;
    }

    let significand = 0x0080_0000 | mantissa;
    let unbiased = exponent as i32 - 127;

    // The subnormal range is handled first, from the unrounded significand: the code is
    // round(significand / 2^(14 - unbiased)) because the step is 2^-9. Order matters here. A
    // value that rounds up to 2^-6 is a tie at the subnormal boundary, and deriving it from the
    // carried exponent (as the normal path does) would round it a full step too high. The shift
    // also has to stay below 32: in C a 32-bit shift by 32 or more is undefined, and on the GPU
    // it silently uses the low five bits of the shift amount, which would produce a wrong
    // subnormal instead of zero.
    if unbiased < -6 {
        let shift = 14 - unbiased;
        if shift >= 32 {
            return sign_byte;
        }
        let code = significand >> shift;
        let tail = significand & ((1u32 << shift) - 1);
        let half = 1u32 << (shift - 1);
        let mut rounded = code;
        if tail > half || (tail == half && (rounded & 1) != 0) {
            rounded += 1;
        }
        if rounded >= 8 {
            return sign_byte | 0x08; // 2^-6, the smallest normal
        }
        return sign_byte | rounded as u8;
    }

    // Normal range: E4M3 keeps three of the 23 mantissa bits, so the rounding point is bit 20 of
    // the 24-bit significand.
    let mut kept = significand >> 20;
    let remainder = significand & 0x000F_FFFF;
    let mut exponent_value = unbiased;
    if remainder > 0x0008_0000 || (remainder == 0x0008_0000 && (kept & 1) != 0) {
        kept += 1;
    }
    if kept == 16 {
        kept = 8;
        exponent_value += 1;
    }
    // Saturation. Exponent field 15 with mantissa field 7 is the E4M3 NaN, so a value that
    // rounds up to 1.875 * 2^8 (= 480) has nowhere to go and saturates to 448 rather than
    // producing the NaN code, exactly as CUDA's saturating converter does.
    if exponent_value > 8 || (exponent_value == 8 && kept == 15) {
        return sign_byte | 0x7E; // +-448, the largest E4M3 magnitude
    }
    // E4M3's exponent bias is 7: field 1 is 2^-6 and field 15 is 2^8.
    let exponent_field = (exponent_value + 7) as u32;
    let mantissa_field = kept - 8;
    sign_byte | ((exponent_field as u8) << 3) | mantissa_field as u8
}

/// The E2M1 nibble of a value: round-to-nearest-even, saturating to +-6 (code 0x7).
#[must_use]
pub fn fp4_e2m1_encode(value: f32) -> u8 {
    let bits = value.to_bits();
    let sign = (bits >> 31) & 1;
    let exponent = (bits >> 23) & 0xFF;
    let mantissa = bits & 0x007F_FFFF;
    let sign_nibble = ((sign << 3) as u8) & 0x8;
    let magnitude = bits & 0x7FFF_FFFF;

    if magnitude < 0x0080_0000 {
        // Only values above 0.25 round up to the 0.5 subnormal; ties go to the even code 0.
        let rounds_up = f32::from_bits(magnitude) > 0.25;
        return sign_nibble | u8::from(rounds_up);
    }
    if exponent == 0xFF {
        // E2M1 has no NaN code. NaN becomes positive MAXNORM whatever its sign (CUDA documents
        // this and the golden table records -NaN -> 0x7); an infinity keeps its sign.
        return if mantissa != 0 {
            0x7
        } else {
            sign_nibble | 0x7
        };
    }
    let significand = 0x0080_0000 | mantissa;
    let unbiased = exponent as i32 - 127;

    // Subnormals first, for the same reason as in the E4M3 encoder: the step is 0.5, so the code
    // is round(significand / 2^(22 - unbiased)) and the shift stays below 32. The bias is 1, so
    // the subnormal range is unbiased < 0: 0.5 is code 0x1 and the smallest normal is 1.0.
    if unbiased < 0 {
        let shift = 22 - unbiased;
        if shift >= 32 {
            return sign_nibble;
        }
        let code = significand >> shift;
        let tail = significand & ((1u32 << shift) - 1);
        let half = 1u32 << (shift - 1);
        let mut rounded = code;
        if tail > half || (tail == half && (rounded & 1) != 0) {
            rounded += 1;
        }
        if rounded >= 2 {
            return sign_nibble | 0x2; // 1.0
        }
        return sign_nibble | rounded as u8;
    }

    // Normal range: E2M1 keeps one mantissa bit, so the rounding point is bit 22.
    let mut kept = significand >> 22;
    let remainder = significand & 0x003F_FFFF;
    let mut exponent_value = unbiased;
    if remainder > 0x0020_0000 || (remainder == 0x0020_0000 && (kept & 1) != 0) {
        kept += 1;
    }
    if kept == 4 {
        kept = 2;
        exponent_value += 1;
    }
    if exponent_value > 2 {
        return sign_nibble | 0x7;
    }
    let exponent_field = (exponent_value + 1) as u32;
    let mantissa_field = kept - 2;
    sign_nibble | ((exponent_field as u8) << 1) | mantissa_field as u8
}

/// Exact E4M3 to f32 evaluation, shared with the kernel's decoder.
#[must_use]
pub fn fp8_e4m3_decode(bits: u8) -> f32 {
    let sign = if bits & 0x80 != 0 { -1.0f32 } else { 1.0f32 };
    let exponent = u32::from(bits >> 3) & 0x0F;
    let mantissa = u32::from(bits) & 0x07;
    if exponent == 0 {
        return sign * mantissa as f32 * 0.001_953_125; // man * 2^-9
    }
    if exponent == 15 && mantissa == 7 {
        return f32::from_bits(0x7FC0_0000); // quiet NaN, never produced by the encoder
    }
    let power = f32::from_bits((exponent + 120) << 23);
    sign * power * (1.0 + mantissa as f32 * 0.125)
}

/// Exact E2M1 to f32 evaluation, shared with the kernel's decoder.
#[must_use]
pub fn fp4_e2m1_decode(nibble: u8) -> f32 {
    let sign = if nibble & 0x8 != 0 { -1.0f32 } else { 1.0f32 };
    let exponent = u32::from(nibble >> 1) & 0x03;
    let mantissa = u32::from(nibble) & 0x01;
    if exponent == 0 {
        return sign * mantissa as f32 * 0.5;
    }
    let power = f32::from_bits((exponent + 126) << 23);
    sign * power * (1.0 + mantissa as f32 * 0.5)
}

/// The ue8m0 code for a block maximum and an element format whose maximum exponent is
/// element_emax: 2^(floor(log2(amax)) - element_emax), the smallest power-of-two scale that keeps
/// amax inside the element format's range. The exponent is signed, so a block whose maximum is
/// well below one keeps the element format's full mantissa precision instead of collapsing every
/// element into a subnormal; the code is clamped to [0, 254], the smallest scale ue8m0 expresses
/// being 2^-127.
#[must_use]
pub fn ue8m0_from_amax(amax: f32, element_emax: u32) -> u8 {
    if amax.is_nan() || amax <= 0.0 {
        return UE8M0_BIAS; // a zero block encodes to all-zero codes with scale 1
    }
    let bits = amax.to_bits();
    let exponent_field = (bits >> 23) & 0xFF;
    if exponent_field == 0 {
        return UE8M0_BIAS; // a float subnormal is below any scale this format can emit
    }
    if exponent_field == 0xFF {
        return UE8M0_MAX; // an infinite block maximum takes the largest scale
    }
    let ceiling = i32::from(UE8M0_MAX) - i32::from(UE8M0_BIAS);
    let floor_code = -i32::from(UE8M0_BIAS);
    let mut exponent = ((bits >> 23) as i32 & 0xFF) - 127 - element_emax as i32;
    exponent = exponent.clamp(floor_code, ceiling);
    (exponent + i32::from(UE8M0_BIAS)) as u8
}

/// The value of a ue8m0 scale code.
#[must_use]
pub fn ue8m0_decode(bits: u8) -> f32 {
    if bits == 255 {
        return f32::from_bits(0x7FC0_0000);
    }
    if bits == 0 {
        // 2^-127 is a float subnormal, not a normal: its f32 bits are mantissa 2^22.
        return f32::from_bits(1 << 22);
    }
    f32::from_bits(u32::from(bits) << 23)
}

/// The E4M3 maximum, spelled the way the reference's activation quantiser spells it
/// (kernel.py:44-46, where it is the maximum of torch.float8_e4m3fn: 448).
pub const E4M3_MAX: f32 = 448.0;

/// The floor the reference puts under a block's absolute maximum (kernel.py:76), so that an
/// all-zero block still gets a finite nonzero scale instead of a division by zero.
pub const ACT_QUANT_AMAX_FLOOR: f32 = 1e-4;

/// fast_log2_ceil from the reference's Triton helper (kernel.py:22-27): the f32 exponent field,
/// debiased, plus one when the mantissa is nonzero. That is the ceiling of log2 for a positive
/// finite value, computed on the bits rather than by a library call - and the reference's scales
/// are exactly this function's output, not a mathematical ideal that merely rounds the same way.
#[must_use]
pub fn fast_log2_ceil(value: f32) -> i32 {
    let bits = value.to_bits();
    let exponent = ((bits >> 23) & 0xFF) as i32;
    let mantissa_is_nonzero = (bits & 0x7F_FFFF) != 0;
    exponent - 127 + i32::from(mantissa_is_nonzero)
}

/// fast_pow2 from the same helper (kernel.py:30-33): 2^exponent by writing the biased exponent into
/// an f32. The reachable range here is [-22, 0] (E4M3's 448 down to the 1e-4 amax floor), far inside
/// the format's normal range.
#[must_use]
pub fn fast_pow2(exponent: i32) -> f32 {
    f32::from_bits(((exponent + 127) as u32) << 23)
}

/// The reference's scale for one block: fast_round_scale(amax, 1/448), which is
/// fast_pow2(fast_log2_ceil(amax * fp8_max_inv)) (kernel.py:36-37 and 78).
///
/// Two consequences are worth stating, because they are exactly where this differs from the
/// floor-of-log2 rule that ue8m0_from_amax uses for the checkpoint's weight grids:
///
/// * the scale is the SMALLEST power of two at or above amax/448, so a block never saturates and
///   the clamp to +-448 that follows cannot fire on that block's own values;
/// * the ceiling is taken on the f32 PRODUCT, so the scale is a function of the rounded product
///   rather than of the exact rational amax/448. The reference passes 1/fp8_max as a Python float
///   (kernel.py:45-46); rounding that f64 to f32 and dividing in f32 give the same f32 here, which
///   a test asserts instead of assuming.
#[must_use]
pub fn act_quant_scale(amax: f32) -> f32 {
    fast_pow2(fast_log2_ceil(amax * (1.0 / E4M3_MAX)))
}

/// The ue8m0 code holding a power-of-two scale. The format is a biased exponent (bias 127), so the
/// code IS the f32 exponent field - which is what scale_dtype=torch.float8_e8m0fnu stores
/// (kernel.py:112-114).
///
/// # Panics
/// Panics if the scale is not a positive power of two, which would mean the caller did not build it
/// with act_quant_scale.
#[must_use]
pub fn ue8m0_code_of_power_of_two(scale: f32) -> u8 {
    let bits = scale.to_bits();
    assert!(
        scale > 0.0 && (bits & 0x7F_FFFF) == 0 && ((bits >> 23) & 0xFF) != 0xFF,
        "a ue8m0 code stores a positive power of two, not {scale}"
    );
    ((bits >> 23) & 0xFF) as u8
}

/// The reference's act_quant for one row of 32-value blocks (kernel.py:41-124): returns the E4M3
/// bytes and the per-block ue8m0 bytes, in that order.
///
/// Mirrored rule for rule: ONE absolute maximum per block rather than a running maximum over the
/// row (kernel.py:74); the 1e-4 amax floor (kernel.py:76); the round-up-to-a-power-of-two scale
/// (kernel.py:78); the division by that scale, the clamp to +-448 and the cast to
/// torch.float8_e4m3fn (kernel.py:89-93), whose round-to-nearest-even is the codec this module
/// already pins exhaustively over all 65,536 inputs.
///
/// # Panics
/// Panics if the row is empty or not a whole number of blocks.
#[must_use]
pub fn act_quant_fp8_row(row: &[f32]) -> (Vec<u8>, Vec<u8>) {
    assert!(
        !row.is_empty() && row.len().is_multiple_of(QUANT_BLOCK),
        "act_quant quantises whole {QUANT_BLOCK}-value blocks, not {} values",
        row.len()
    );
    let mut values = Vec::with_capacity(row.len());
    let mut scales = Vec::with_capacity(row.len() / QUANT_BLOCK);
    for block in row.chunks(QUANT_BLOCK) {
        let mut amax = 0.0f32;
        for value in block {
            amax = amax.max(value.abs());
        }
        let amax = amax.max(ACT_QUANT_AMAX_FLOOR);
        let scale = act_quant_scale(amax);
        scales.push(ue8m0_code_of_power_of_two(scale));
        for value in block {
            values.push(fp8_e4m3_encode((value / scale).clamp(-E4M3_MAX, E4M3_MAX)));
        }
    }
    (values, scales)
}

/// The quantization error of the block formats, as a property the tests use: every element of a
/// block must land within half a step of the scale it was quantized with.
#[must_use]
pub fn fp8_block_tolerance(scale: f32) -> f32 {
    scale * 0.0625 // half of the 3-bit (1/8) mantissa step at the block's magnitude
}

/// Quantizes one row of floats with a ue8m0 scale per 32 values, exactly as the kernels do.
///
/// # Panics
/// Panics if the lengths do not agree with a 32-value block layout.
pub fn quantize_row_e4m3(src: &[f32], dst: &mut [u8], scales: &mut [u8]) {
    assert_eq!(
        src.len(),
        dst.len(),
        "quantize_row_e4m3: source and destination differ"
    );
    assert_eq!(
        src.len() % QUANT_BLOCK,
        0,
        "quantize_row_e4m3: row is not a whole block count"
    );
    assert_eq!(
        scales.len(),
        src.len() / QUANT_BLOCK,
        "quantize_row_e4m3: scale count"
    );
    for (block, scale_slot) in scales.iter_mut().enumerate() {
        let base = block * QUANT_BLOCK;
        let amax = src[base..base + QUANT_BLOCK]
            .iter()
            .fold(0.0f32, |acc, value| acc.max(value.abs()));
        let scale = ue8m0_from_amax(amax, E4M3_ELEMENT_EMAX);
        *scale_slot = scale;
        let inverse = 1.0 / ue8m0_decode(scale);
        for (slot, value) in dst[base..base + QUANT_BLOCK]
            .iter_mut()
            .zip(&src[base..base + QUANT_BLOCK])
        {
            *slot = fp8_e4m3_encode(value * inverse);
        }
    }
}

/// The number of bytes an encoded row occupies: one byte per element plus one scale per block.
#[must_use]
pub fn encoded_row_bytes(count: usize) -> usize {
    count + count / QUANT_BLOCK
}

/// Checks the layout constants against the parsed kernel header, so a drift in
/// kernels/m4_common_sm121.cuh breaks the build rather than a test on hardware.
///
/// # Panics
/// Panics when a constant in the header disagrees with this module.
pub fn assert_matches_kernel_header() {
    let header = m4_abi::header_source();
    assert_eq!(
        QUANT_BLOCK as u64,
        m4_abi::header_constant(header, "SPARK_M4_QUANT_BLOCK"),
        "SPARK_M4_QUANT_BLOCK"
    );
    assert_eq!(
        u64::from(UE8M0_BIAS),
        m4_abi::header_constant(header, "SPARK_M4_UE8M0_BIAS"),
        "SPARK_M4_UE8M0_BIAS"
    );
    assert_eq!(
        u64::from(UE8M0_MAX),
        m4_abi::header_constant(header, "SPARK_M4_UE8M0_MAX"),
        "SPARK_M4_UE8M0_MAX"
    );
}
